     * Refused with nothing to number: a bulk settle that settles none is no batch.
     */
    @Transactional
    public int numberSettleBatch(String sheetId, List<Long> ids) {
        if (ids.isEmpty()) {
            throw new IllegalArgumentException("A batch needs at least one claim.");
        }
